//! anygen-mockd — local mock of the anygen gateway protocol.
//!
//! Implements the unified async job protocol so the CLI can be developed and
//! demonstrated end-to-end without the real billing backend:
//!
//!   POST /v1/{image|video|music|speech}/generations -> 202 {job_id, credits_charged, balance}
//!   GET  /v1/jobs/{id}                              -> states queued|running|succeeded|failed
//!   GET  /v1/models                                 -> catalog with credit pricing
//!   GET  /v1/account/balance                        -> credits
//!   GET  /assets/{file}                             -> dummy bytes for downloads
//!
//! Behaviours simulated deliberately because the real gateway promises them:
//! - submit-time charging (credits deducted on 202)
//! - automatic refund when a job fails (prompt contains "__fail__")
//! - insufficient credits rejection with HTTP 402
//! - preview models reject submissions
//!
//! Any API key starting with `ag-sk-` is accepted.

use anyhow::Result;
use clap::Parser;
use serde_json::{json, Value};
use std::collections::HashMap;
use std::io::Read;
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};
use tiny_http::{Header, Response, Server};

#[derive(Parser)]
#[command(name = "anygen-mockd", about = "Local mock of the anygen gateway")]
struct Args {
    /// TCP port to listen on
    #[arg(long, default_value_t = 8927)]
    port: u16,

    /// Starting credit balance for the mock account
    #[arg(long, default_value_t = 5000.0)]
    balance: f64,
}

struct ModelDef {
    id: &'static str,
    display_name: &'static str,
    modality: &'static str,
    status: &'static str,
    unit: &'static str,
    credits_per_unit: f64,
    avg_latency_secs: u64,
    /// Simulated seconds until the job reaches "succeeded"
    delay_secs: u64,
}

const MODELS: &[ModelDef] = &[
    ModelDef { id: "nano-banana", display_name: "Nano Banana (Gemini Flash Image)", modality: "image", status: "available", unit: "image", credits_per_unit: 12.0, avg_latency_secs: 20, delay_secs: 4 },
    ModelDef { id: "seedream-4.0", display_name: "Seedream 4.0", modality: "image", status: "available", unit: "image", credits_per_unit: 18.0, avg_latency_secs: 40, delay_secs: 5 },
    ModelDef { id: "seedance-2.5", display_name: "Seedance 2.5", modality: "video", status: "available", unit: "video_second", credits_per_unit: 8.0, avg_latency_secs: 300, delay_secs: 10 },
    ModelDef { id: "seedance-2.0", display_name: "Seedance 2.0", modality: "video", status: "preview", unit: "video_second", credits_per_unit: 5.0, avg_latency_secs: 240, delay_secs: 9 },
    ModelDef { id: "veo-3.1", display_name: "Veo 3.1", modality: "video", status: "preview", unit: "video_second", credits_per_unit: 60.0, avg_latency_secs: 600, delay_secs: 11 },
    ModelDef { id: "minimax-music", display_name: "MiniMax Music", modality: "music", status: "preview", unit: "song", credits_per_unit: 30.0, avg_latency_secs: 120, delay_secs: 6 },
    ModelDef { id: "minimax-tts", display_name: "MiniMax TTS", modality: "speech", status: "available", unit: "1000_chars", credits_per_unit: 6.0, avg_latency_secs: 15, delay_secs: 3 },
];

fn model(id: &str) -> Option<&'static ModelDef> {
    MODELS.iter().find(|m| m.id == id)
}

struct Job {
    model_id: &'static str,
    modality_kind: &'static str,
    prompt: String,
    n_outputs: usize,
    credits_charged: f64,
    start: Instant,
    delay: Duration,
    terminal_notified: bool,
}

/// Evaluation of a job's current lifecycle position. Terminal transitions are
/// frozen by flipping `terminal_notified` so repeated polls stay consistent.
fn evaluate(job: &mut Job) -> (&'static str, Option<String>) {
    if job.terminal_notified {
        return ("succeeded", None);
    }
    // Deliberate failure mode for demos/tests: prompt containing __fail__
    if job.prompt.contains("__fail__") && job.start.elapsed() >= job.delay / 2 {
        return ("failed", Some("__fail__ marker in prompt".into()));
    }
    if job.start.elapsed() >= job.delay {
        ("succeeded", None)
    } else if job.start.elapsed() >= Duration::from_millis(800) {
        ("running", None)
    } else {
        ("queued", None)
    }
}

#[derive(Default)]
struct State {
    balance: Mutex<f64>,
    jobs: Mutex<HashMap<String, Job>>,
    next_id: AtomicU64,
}

impl State {
    fn balance(&self) -> f64 {
        *self.balance.lock().unwrap()
    }

    fn charge(&self, cost: f64) -> bool {
        let mut bal = self.balance.lock().unwrap();
        if *bal < cost {
            return false;
        }
        *bal -= cost;
        true
    }

    fn refund(&self, amount: f64) {
        *self.balance.lock().unwrap() += amount;
    }
}

enum Reply {
    Json(u16, Value),
    Data(u16, &'static str, Vec<u8>),
}

fn header(ct: &[u8]) -> Header {
    Header::from_bytes(&b"Content-Type"[..], ct).unwrap()
}

fn error_body(code: &str, message: &str, extra: Value) -> Value {
    let mut e = json!({ "code": code, "message": message });
    if let (Value::Object(a), Value::Object(b)) = (&mut e, extra) {
        a.extend(b);
    }
    json!({ "error": e })
}

fn api_key_of(req_headers: &[tiny_http::Header]) -> Option<String> {
    req_headers
        .iter()
        .find(|h| h.field.equiv("x-api-key"))
        .map(|h| h.value.as_str().to_string())
}

// ---------------------------------------------------------------------------
// Routing
// ---------------------------------------------------------------------------

fn route(state: &State, method: &str, path: &str, headers: &[tiny_http::Header], body_reader: &mut dyn Read) -> Reply {
    if method == "GET" && path.starts_with("/assets/") {
        return asset(path.trim_start_matches("/assets/"));
    }

    if !path.starts_with("/v1/") {
        return Reply::Json(404, error_body("not_found", "unknown path", json!({})));
    }

    let key = api_key_of(headers);
    match key.as_deref() {
        Some(k) if k.starts_with("ag-sk-") => {}
        _ => {
            return Reply::Json(
                401,
                error_body("invalid_api_key", "send an ag-sk-… key in the x-api-key header", json!({})),
            )
        }
    }

    match (method, path) {
        ("GET", "/v1/models") => Reply::Json(200, json!({ "models": models_catalog() })),

        ("GET", "/v1/account/balance") => Reply::Json(200, json!({ "credits": state.balance() })),

        ("POST", p) if p.ends_with("/generations") => submit(state, p, body_reader),

        ("GET", p) if p.starts_with("/v1/jobs/") => {
            query_job(state, p.trim_start_matches("/v1/jobs/"))
        }

        _ => Reply::Json(404, error_body("not_found", "unsupported route", json!({}))),
    }
}

fn submit(state: &State, path: &str, body_reader: &mut dyn Read) -> Reply {
    let modality = path.trim_start_matches("/v1/").trim_end_matches("/generations");

    let mut raw = String::new();
    let _ = body_reader.read_to_string(&mut raw);
    let parsed: Value = match serde_json::from_str(&raw) {
        Ok(v) => v,
        Err(_) => return Reply::Json(400, error_body("bad_request", "body must be JSON", json!({}))),
    };

    let model_id = parsed["model"].as_str().unwrap_or("");
    let prompt = parsed["prompt"].as_str().unwrap_or("").to_string();
    if model_id.is_empty() || prompt.is_empty() {
        return Reply::Json(400, error_body("bad_request", "model and prompt are required", json!({})));
    }

    let Some(m) = model(model_id) else {
        return Reply::Json(400, error_body("model_not_found", &format!("unknown model '{model_id}'"), json!({})));
    };
    if m.modality != modality {
        return Reply::Json(
            400,
            error_body(
                "modality_mismatch",
                &format!("model '{model_id}' belongs to '{}', got '{modality}'", m.modality),
                json!({}),
            ),
        );
    }
    if m.status != "available" {
        return Reply::Json(
            400,
            error_body("model_preview", &format!("model '{model_id}' is in preview and not yet accepting jobs"), json!({})),
        );
    }

    let params = parsed.get("params").cloned().unwrap_or(json!({}));
    let (cost, n_outputs) = price_quote(m, &params);

    // Charged-on-submit semantics; insufficient balance rejects the whole job.
    if !state.charge(cost) {
        return Reply::Json(
            402,
            error_body(
                "insufficient_credits",
                "top up at https://console.anygen.dev/billing",
                json!({ "required": cost, "balance": state.balance() }),
            ),
        );
    }

    let id_num = state.next_id.fetch_add(1, Ordering::SeqCst);
    let job_id = format!("job_{:012x}", id_num);

    state.jobs.lock().unwrap().insert(
        job_id.clone(),
        Job {
            model_id: m.id,
            modality_kind: match m.modality {
                "video" => "video",
                "music" => "music",
                "speech" => "speech",
                _ => "image",
            },
            prompt,
            n_outputs,
            credits_charged: cost,
            start: Instant::now(),
            delay: Duration::from_secs(m.delay_secs),
            terminal_notified: false,
        },
    );

    Reply::Json(
        202,
        json!({
            "job_id": job_id,
            "state": "queued",
            "credits_charged": cost,
            "balance": state.balance(),
        }),
    )
}

fn query_job(state: &State, job_id: &str) -> Reply {
    let mut jobs = state.jobs.lock().unwrap();
    let Some(job) = jobs.get_mut(job_id) else {
        return Reply::Json(404, error_body("job_not_found", &format!("no job '{job_id}'"), json!({})));
    };

    let credits = job.credits_charged;
    let model_id = job.model_id;
    let (st, fail_reason) = evaluate(job);

    if st == "failed" {
        if !job.terminal_notified {
            job.terminal_notified = true;
            state.refund(credits);
        }
        drop(jobs);
        return Reply::Json(
            200,
            json!({
                "job_id": job_id,
                "model": model_id,
                "state": "failed",
                "credits_charged": credits,
                "error": { "code": "generation_failed", "message": fail_reason.unwrap_or_default() },
                "balance": state.balance(),
            }),
        );
    }

    if st == "succeeded" {
        if !job.terminal_notified {
            job.terminal_notified = true;
        }
        let outputs = outputs_body(job, job_id);
        drop(jobs);
        return Reply::Json(
            200,
            json!({
                "job_id": job_id,
                "model": model_id,
                "state": "succeeded",
                "credits_charged": credits,
                "outputs": outputs,
            }),
        );
    }

    Reply::Json(
        200,
        json!({
            "job_id": job_id,
            "model": model_id,
            "state": st,
            "credits_charged": credits,
        }),
    )
}

fn num_param(params: &Value, key: &str) -> Option<u64> {
    params[key]
        .as_u64()
        .or_else(|| params[key].as_str().and_then(|s| s.parse().ok()))
}

fn price_quote(m: &ModelDef, params: &Value) -> (f64, usize) {
    let mut n_outputs = 1usize;
    match m.unit {
        "video_second" => {
            let secs = num_param(params, "duration_seconds").unwrap_or(5);
            return ((m.credits_per_unit * secs as f64).ceil(), 1);
        }
        "image" | "song" => {
            if let Some(n) = num_param(params, "n") {
                n_outputs = n.clamp(1, 4) as usize;
            }
        }
        _ => {}
    }
    (m.credits_per_unit * n_outputs.max(1) as f64, n_outputs)
}

fn outputs_body(job: &Job, job_id: &str) -> Vec<Value> {
    (0..job.n_outputs)
        .map(|i| {
            let suffix = if job.n_outputs > 1 {
                format!("_{i}")
            } else {
                String::new()
            };
            let ext = match job.modality_kind {
                "video" => "mp4",
                "music" | "speech" => "wav",
                _ => "png",
            };
            json!({
                "type": job.modality_kind,
                "format": ext,
                "url": format!("/assets/{job_id}{suffix}.{ext}"),
            })
        })
        .collect()
}

fn models_catalog() -> Vec<Value> {
    MODELS
        .iter()
        .map(|m| {
            json!({
                "id": m.id,
                "display_name": m.display_name,
                "modality": m.modality,
                "status": m.status,
                "unit": m.unit,
                "credits_per_unit": m.credits_per_unit,
                "avg_latency_secs": m.avg_latency_secs,
            })
        })
        .collect()
}

fn asset(name: &str) -> Reply {
    let (ct, body): (&'static str, Vec<u8>) = if name.ends_with(".png") {
        (
            "image/png",
            vec![
                0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A, 0x00, 0x00, 0x00, 0x0D, 0x49,
                0x48, 0x44, 0x52, 0x00, 0x00, 0x00, 0x01, 0x00, 0x00, 0x00, 0x01, 0x08, 0x06,
                0x00, 0x00, 0x00, 0x1F, 0x15, 0xC4, 0x89, 0x00, 0x00, 0x00, 0x0D, 0x49, 0x44,
                0x41, 0x54, 0x78, 0x9C, 0x62, 0x00, 0x01, 0x00, 0x00, 0x05, 0x00, 0x01, 0x0D,
                0x0A, 0x2D, 0xB4, 0x00, 0x00, 0x00, 0x00, 0x49, 0x45, 0x4E, 0x44, 0xAE, 0x42,
                0x60, 0x82,
            ],
        )
    } else {
        ("application/octet-stream", b"ANYGEN-MOCK-MEDIA\n".repeat(2048))
    };
    Reply::Data(200, ct, body)
}

fn main() -> Result<()> {
    let args = Args::parse();
    let addr = format!("127.0.0.1:{}", args.port);
    let server = Server::http(&addr).map_err(|e| anyhow::anyhow!("cannot bind {addr}: {e}"))?;
    let state = Arc::new(State {
        balance: Mutex::new(args.balance),
        ..Default::default()
    });

    println!("anygen-mockd listening on http://{addr}");
    println!("Try:");
    println!("  export ANYGEN_BASE_URL=http://{addr}");
    println!("  export ANYGEN_API_KEY=ag-sk-test");
    println!("  cargo run --bin anygen -- models");
    println!("  cargo run --bin anygen -- video \"A cat surfing\" --model seedance-2.5 -E duration_seconds=8");
    println!();

    for mut req in server.incoming_requests() {
        let path = req.url().split('?').next().unwrap_or("/").to_string();
        let method = req.method().as_str().to_uppercase();
        let headers: Vec<tiny_http::Header> = req.headers().to_vec();

        let reply = route(&state, &method, &path, &headers, req.as_reader());

        let result = match reply {
            Reply::Json(code, v) => {
                let body = serde_json::to_string_pretty(&v).unwrap_or_default();
                req.respond(Response::from_string(body).with_status_code(code).with_header(header(b"application/json")))
            }
            Reply::Data(code, ct, bytes) => req.respond(
                Response::from_data(bytes)
                    .with_status_code(code)
                    .with_header(header(ct.as_bytes())),
            ),
        };

        if let Err(e) = result {
            eprintln!("request failed: {e}");
        }
    }
    Ok(())
}

