use anyhow::{Context, Result};
use clap::Args;
use console::style;
use std::io::Write;

use crate::client::GatewayClient;
use crate::config::AppConfig;

#[derive(Args, Debug)]
pub struct LoginArgs {
    /// Paste an existing API key non-interactively (else prompts / opens browser)
    #[arg(long)]
    pub key: Option<String>,
}

pub async fn login(cfg: &mut AppConfig, args: &LoginArgs) -> Result<()> {
    let key = match &args.key {
        Some(k) => k.clone(),
        None => {
            let url = "https://console.anygen.dev/keys";
            println!("Open {} to create an API key, then paste it here.", style(url).cyan());
            if let Err(e) = open_browser(url) {
                eprintln!("(could not launch browser: {e})");
            }
            print!("API key: ");
            std::io::stdout().flush()?;
            let mut input = String::new();
            std::io::stdin()
                .read_line(&mut input)
                .context("failed to read API key")?;
            input.trim().to_string()
        }
    };

    if key.is_empty() {
        anyhow::bail!("empty API key");
    }
    if !key.starts_with("ag-sk-") {
        anyhow::bail!("anygen keys start with 'ag-sk-' — got '{}...'", &key.chars().take(8).collect::<String>());
    }

    cfg.api_key = Some(key);
    cfg.save().with_context(|| "failed to save config")?;

    let path = AppConfig::config_path()?;
    eprintln!(
        "{} Logged in. Key stored at {}",
        style("✓").green().bold(),
        path.display()
    );
    Ok(())
}

pub async fn logout() -> Result<()> {
    let mut cfg = AppConfig::load()?;
    cfg.api_key = None;
    cfg.save()?;
    eprintln!("{} Logged out.", style("✓").green().bold());
    Ok(())
}

pub async fn balance(client: &GatewayClient) -> Result<()> {
    let b = client.balance().await?;
    println!("credits: {}", style(b.credits).green().bold());
    Ok(())
}

fn open_browser(url: &str) -> Result<()> {
    #[cfg(target_os = "macos")]
    let program = "open";
    #[cfg(not(target_os = "macos"))]
    let program = "xdg-open";
    std::process::Command::new(program)
        .arg(url)
        .spawn()
        .map(|_| ())
        .with_context(|| format!("failed to spawn {program}"))
}

use anyhow::Result;
use clap::Args;
use console::style;

use crate::config::AppConfig;

#[derive(Args, Debug, Clone)]
pub struct ConfigArgs {
    #[command(subcommand)]
    pub command: ConfigCommand,
}

#[derive(clap::Subcommand, Debug, Clone)]
pub enum ConfigCommand {
    /// Interactive first-run setup
    Init,
    /// Print all config values
    List,
    /// Get one value: anygen config get base_url
    Get { key: String },
    /// Set one value: anygen config set model_video seedance-2.5
    Set { key: String, value: String },
}

const CONFIG_KEYS: &[&str] = AppConfig::CONFIG_KEYS;

pub async fn execute(command: ConfigCommand) -> Result<()> {
    match command {
        ConfigCommand::Init => {
            let mut cfg = AppConfig::load()?;
            for key in ["model_image", "model_video", "output_dir"] {
                print!("{key} [{}]: ", cfg.get(key).unwrap_or_default());
                use std::io::Write;
                std::io::stdout().flush()?;
                let mut input = String::new();
                std::io::stdin().read_line(&mut input)?;
                let v = input.trim();
                if !v.is_empty() {
                    cfg.set(key, v)?;
                }
            }
            cfg.save()?;
            eprintln!("{} Config saved to {:?}", style("✓").green().bold(), AppConfig::config_path()?);
            eprintln!("Next: run `anygen login`.");
        }
        ConfigCommand::List => {
            let cfg = AppConfig::load()?;
            for key in CONFIG_KEYS {
                println!("{key:<14} = {}", cfg.get(key).unwrap_or_else(|| "-".into()));
            }
        }
        ConfigCommand::Get { key } => {
            let cfg = AppConfig::load()?;
            match cfg.get(&key) {
                Some(v) => println!("{v}"),
                None => anyhow::bail!("unknown config key: {key}. Valid keys: {}", CONFIG_KEYS.join(", ")),
            }
        }
        ConfigCommand::Set { key, value } => {
            let mut cfg = AppConfig::load()?;
            cfg.set(&key, &value)
                .map_err(|e| anyhow::anyhow!("{e}. Valid keys: {}", CONFIG_KEYS.join(", ")))?;
            cfg.save()?;
            eprintln!("{} {key} = {value}", style("✓").green().bold());
        }
    }
    Ok(())
}

use anyhow::{bail, Result};
use clap::Args;
use std::collections::BTreeMap;
use std::path::PathBuf;

use crate::client::types::{JobResponse, Modality, SubmitJobRequest};
use crate::client::GatewayClient;
use crate::config::AppConfig;
use crate::core::{downloader, poller};
use crate::store::TaskStore;
use crate::ui;

#[derive(Args, Debug, Clone)]
pub struct GenerateArgs {
    /// Prompt text
    pub prompt: String,

    /// Model id from `anygen models` (defaults to config model_<modality>)
    #[arg(short, long)]
    pub model: Option<String>,

    /// Reference input file/URL for image-to-image / image-to-video / voice clone
    #[arg(short, long)]
    pub reference: Option<String>,

    /// Video duration in seconds
    #[arg(long)]
    pub duration: Option<u8>,

    /// Aspect ratio, e.g. 16:9
    #[arg(long)]
    pub ratio: Option<String>,

    /// Resolution, e.g. 1080p
    #[arg(long)]
    pub resolution: Option<String>,

    /// Image size token (2k/3k/4k) or explicit WxH
    #[arg(long)]
    pub size: Option<String>,

    /// Number of outputs (images / samples)
    #[arg(short = 'n', long)]
    pub count: Option<u32>,

    /// Voice id for speech generation
    #[arg(long)]
    pub voice: Option<String>,

    /// Wait for completion and download outputs [default: wait]
    #[arg(long)]
    pub no_wait: bool,

    /// Output base path (extension auto-appended); defaults to ./anygen_<job>
    #[arg(short, long)]
    pub output: Option<PathBuf>,

    /// Max seconds to wait before returning (job keeps running server-side)
    #[arg(long)]
    pub timeout: Option<u64>,

    /// Emit machine-readable JSON
    #[arg(long)]
    pub json: bool,

    /// Suppress all decorative output; print ids/paths only
    #[arg(long)]
    pub quiet: bool,

    /// Passthrough provider parameter k=v (repeatable), e.g. -E watermark=false
    #[arg(short = 'E', long = "extra")]
    pub extra: Vec<String>,
}

impl GenerateArgs {
    fn extra_map(&self) -> Result<BTreeMap<String, serde_json::Value>> {
        let mut map = serde_json::Map::new();
        for kv in &self.extra {
            match kv.split_once('=') {
                Some((k, v)) => {
                    map.insert(
                        k.trim().to_string(),
                        serde_json::Value::String(v.trim().to_string()),
                    );
                }
                None => bail!("--extra expects key=value, got '{kv}'"),
            }
        }
        // Typed convenience flags fold into params so the gateway sees one object.
        if let Some(v) = self.duration {
            map.insert("duration_seconds".into(), v.into());
        }
        if let Some(v) = &self.ratio {
            map.insert("ratio".into(), v.clone().into());
        }
        if let Some(v) = &self.resolution {
            map.insert("resolution".into(), v.clone().into());
        }
        if let Some(v) = &self.size {
            map.insert("size".into(), v.clone().into());
        }
        if let Some(v) = self.count {
            map.insert("n".into(), v.into());
        }
        if let Some(v) = &self.voice {
            map.insert("voice".into(), v.clone().into());
        }
        Ok(BTreeMap::from_iter(map.into_iter()))
    }
}

pub async fn generate(client: &GatewayClient, cfg: &AppConfig, modality: Modality, args: GenerateArgs) -> Result<()> {
    let default_model_key = format!("model_{}", modality.as_str());
    let model = args
        .model
        .clone()
        .or_else(|| cfg.get(&default_model_key))
        .ok_or_else(|| {
            anyhow::anyhow!("no model specified. Use --model or `anygen config set {default_model_key} <id>`; see `anygen models`")
        })?;

    let params = {
        let m = args.extra_map()?;
        if m.is_empty() {
            None
        } else {
            Some(m.into_iter().collect::<serde_json::Map<_, _>>())
        }
    };

    let req = SubmitJobRequest {
        model,
        prompt: args.prompt.clone(),
        reference: args.reference.clone(),
        params,
    };

    let submit = client.submit(modality, &req).await?;
    let job_id = submit.job_id.clone();

    if let Ok(store) = TaskStore::open() {
        let _ = store.insert(&job_id, &args.prompt, &req.model, modality.as_str(), submit.credits_charged);
    }

    if args.json && args.no_wait {
        println!("{}", serde_json::to_string_pretty(&submit)?);
        return Ok(());
    }

    if !args.quiet {
        ui::print_job_created(&job_id, submit.credits_charged, submit.balance);
    } else if args.no_wait {
        println!("{job_id}");
    }

    if args.no_wait {
        return Ok(());
    }

    let poll_opts = poller::PollOptions {
        timeout: std::time::Duration::from_secs(args.timeout.unwrap_or(cfg.timeout_secs)),
        initial_interval: std::time::Duration::from_secs(1),
        strict: false,
    };

    match poller::poll_until_done(client, &job_id, &poll_opts, args.quiet).await? {
        poller::PollResult::Completed(job) => handle_completed(client, cfg, job, &args).await,
        poller::PollResult::TimedOut { job_id, elapsed, .. } => {
            handle_timeout(&job_id, elapsed.as_secs(), &args);
            Ok(())
        }
    }
}

async fn handle_completed(
    client: &GatewayClient,
    cfg: &AppConfig,
    job: JobResponse,
    args: &GenerateArgs,
) -> Result<()> {
    if let Ok(store) = TaskStore::open() {
        let first_url = job.outputs.first().map(|o| o.url.as_str());
        let _ = store.update_status(&job.job_id, job.state.to_string().as_str(), first_url);
    }

    if !job.state.is_success() {
        let msg = job
            .error
            .as_ref()
            .and_then(|e| e.message.clone())
            .unwrap_or_else(|| "unknown error".into());
        // Failed jobs are refunded by the gateway automatically.
        ui::print_error(&format!(
            "Job {} {}: {msg} (credits were refunded automatically)",
            style_job(&job.job_id),
            job.state
        ));
        if args.json {
            println!("{}", serde_json::to_string_pretty(&job)?);
        }
        std::process::exit(1);
    }

    if args.json {
        println!("{}", serde_json::to_string_pretty(&job)?);
    }

    if args.no_wait || job.outputs.is_empty() {
        return Ok(());
    }

    let ext_by_type = |kind: &str, fmt: Option<&str>| -> String {
        fmt.map(|s| s.to_string()).unwrap_or_else(|| match kind {
            "image" => "png".into(),
            "video" => "mp4".into(),
            "music" | "speech" | "audio" => "wav".into(),
            other => other.to_string(),
        })
    };

    let mut saved_paths = Vec::new();
    for (i, out) in job.outputs.iter().enumerate() {
        let suffix = if job.outputs.len() > 1 {
            format!("_{}", i + 1)
        } else {
            String::new()
        };
        let base = args.output.clone().unwrap_or_else(|| {
            PathBuf::from(cfg.output_dir.clone())
                .join(format!("anygen_{}{}", job.job_id, suffix))
        });
        // If user gave an extension keep it, else derive from output type.
        let path = if base.extension().is_some() && job.outputs.len() == 1 {
            base
        } else {
            let ext = ext_by_type(&out.kind, out.format.as_deref());
            base.with_extension(ext)
        };
        downloader::download_file(&client.resolve_asset_url(&out.url), &path, args.quiet).await?;
        if let Ok(store) = TaskStore::open() {
            let _ = store.update_output_path(&job.job_id, &path.display().to_string());
        }
        saved_paths.push(path);
    }

    if args.json {
        return Ok(());
    }
    if args.quiet {
        for p in saved_paths {
            println!("{}", p.display());
        }
    } else {
        for p in saved_paths {
            ui::print_downloaded(&p.display().to_string());
        }
    }
    Ok(())
}

fn handle_timeout(job_id: &str, elapsed_secs: u64, args: &GenerateArgs) {
    if args.json {
        println!(
            "{}",
            serde_json::json!({ "job_id": job_id, "state": "timeout", "elapsed_secs": elapsed_secs })
        );
    } else if !args.quiet {
        ui::print_timeout_hint(job_id, elapsed_secs);
    } else {
        println!("{job_id}");
    }
}

