pub struct DownloadArgs {
    pub job_id: String,

    #[arg(short, long)]
    pub output: Option<PathBuf>,
}

pub async fn status(client: &GatewayClient, args: &StatusArgs) -> Result<()> {
    if !args.wait {
        let job = client.query_job(&args.job_id).await?;
        if args.json {
            println!("{}", serde_json::to_string_pretty(&job)?);
        } else {
            ui::print_job_state(&job.job_id, &job.state);
            for out in &job.outputs {
                eprintln!("  [{}] {}", out.kind, out.url);
            }
        }
        return Ok(());
    }

    let poll_opts = poller::PollOptions::default();
    match poller::poll_until_done(client, &args.job_id, &poll_opts, false).await? {
        poller::PollResult::Completed(job) => {
            if args.json {
                println!("{}", serde_json::to_string_pretty(&job)?);
            } else {
                ui::print_job_state(&job.job_id, &job.state);
                for out in &job.outputs {
                    eprintln!("  [{}] {}", out.kind, out.url);
                }
            }
            if !job.state.is_success() {
                std::process::exit(1);
            }
            Ok(())
        }
        poller::PollResult::TimedOut { job_id, elapsed, .. } => {
            ui::print_timeout_hint(&job_id, elapsed.as_secs());
            std::process::exit(2);
        }
    }
}

pub async fn list(args: &ListArgs) -> Result<()> {
    let store = TaskStore::open()?;
    let jobs = store.list(args.limit, Some(&args.status))?;

    if args.json {
        println!("{}", serde_json::to_string_pretty(&jobs)?);
        return Ok(());
    }

    println!(
        "{:<24} {:<8} {:<18} {:<10} {:>9}  {}",
        "JOB", "KIND", "MODEL", "STATUS", "CREDITS", "PROMPT"
    );
    for j in jobs {
        let st = match j.status.as_str() {
            "succeeded" => style("succeeded").green().to_string(),
            "failed" | "canceled" => style(j.status.clone()).red().to_string(),
            "running" | "queued" => style(j.status.clone()).yellow().to_string(),
            other => other.to_string(),
        };
        println!(
            "{:<24} {:<8} {:<18} {:<10} {:>9}  {}",
            style(&j.job_id).cyan(),
            j.modality,
            j.model,
            st,
            format!("{:.0}", j.credits),
            truncate(&j.prompt, 60),
        );
    }
    Ok(())
}

pub async fn download(cfg: &AppConfig, client: &GatewayClient, args: &DownloadArgs) -> Result<()> {
    let job = client.query_job(&args.job_id).await?;

    if !job.state.is_terminal() {
        ui::print_job_state(&job.job_id, &job.state);
        anyhow::bail!("job {} is not finished yet — use `anygen status {} --wait` first", job.job_id, job.job_id);
    }
    if !job.state.is_success() {
        anyhow::bail!("job {} did not succeed (state: {})", job.job_id, job.state);
    }

    let mut n = 0;
    for out in &job.outputs {
        n += 1;
        let base = args.output.clone().unwrap_or_else(|| {
            PathBuf::from(cfg.output_dir.clone()).join(format!("anygen_{}_{}", job.job_id, n))
        });
        let path = if base.extension().is_some() && job.outputs.len() == 1 {
            base
        } else {
            let ext = match out.kind.as_str() {
                "video" => "mp4",
                "music" | "speech" | "audio" => "wav",
                _ => "png",
            };
            base.with_extension(ext)
        };
        downloader::download_file(&client.resolve_asset_url(&out.url), &path, false).await?;
        if let Ok(store) = TaskStore::open() {
            let _ = store.update_output_path(&job.job_id, &path.display().to_string());
        }
        ui::print_downloaded(&path.display().to_string());
    }
    Ok(())
}

fn truncate(s: &str, max: usize) -> String {
    if s.chars().count() <= max {
        s.to_string()
    } else {
        let t: String = s.chars().take(max - 1).collect();
        format!("{t}…")
    }
}

