use anyhow::{Context, Result};
use error::GatewayError;
use reqwest::header::{HeaderMap, HeaderValue, CONTENT_TYPE};
use types::{
    BalanceResponse, JobResponse, ModelsResponse, Modality, SubmitJobRequest, SubmitJobResponse,
};

/// Client for the anygen unified gateway protocol.
///
/// Every modality (image / video / music / speech) uses the same async job
/// lifecycle: submit -> job_id -> poll until terminal state. Provider-specific
/// sync APIs are wrapped into jobs by the gateway, so the CLI has exactly one
/// code path.
pub struct GatewayClient {
    http: reqwest::Client,
    base_url: String,
    #[allow(dead_code)]
    api_key: String,
}

impl GatewayClient {
    pub fn new(base_url: &str, api_key: &str) -> Result<Self> {
        let mut headers = HeaderMap::new();
        headers.insert(CONTENT_TYPE, HeaderValue::from_static("application/json"));
        headers.insert(
            "x-api-key",
            HeaderValue::from_str(api_key).context("invalid API key characters")?,
        );

        let http = reqwest::Client::builder()
            .default_headers(headers)
            .timeout(std::time::Duration::from_secs(30))
            .build()?;

        Ok(Self {
            http,
            base_url: base_url.trim_end_matches('/').to_string(),
            api_key: api_key.to_string(),
        })
    }

    fn url(&self, path: &str) -> String {
        format!("{}{}", self.base_url, path)
    }

    /// Resolve gateway-relative asset URLs ("/assets/x.png") against the
    /// configured base; absolute URLs pass through untouched.
    pub fn resolve_asset_url(&self, url: &str) -> String {
        if url.starts_with('/') {
            format!("{}{}", self.base_url, url)
        } else {
            url.to_string()
        }
    }

    async fn send(&self, req: reqwest::RequestBuilder) -> Result<String> {
        let resp = req.send().await?;
        let status = resp.status();

        if status == reqwest::StatusCode::TOO_MANY_REQUESTS {
            anyhow::bail!(GatewayError::RateLimited);
        }
        if status == reqwest::StatusCode::UNAUTHORIZED {
            anyhow::bail!(GatewayError::InvalidApiKey);
        }
        if status == reqwest::StatusCode::PAYMENT_REQUIRED {
            // Best-effort parse of {error:{code,message}} with credit details.
            if let Ok(v) = resp.json::<serde_json::Value>().await {
                let err = &v["error"];
                let required = err["required"].as_f64().unwrap_or(0.0);
                let balance = err["balance"].as_f64().unwrap_or(0.0);
                return Err(GatewayError::InsufficientCredits { required, balance }.into());
            }
            anyhow::bail!(GatewayError::Api {
                status: 402,
                message: "insufficient credits".into(),
            });
        }

        let body = resp.text().await?;
        if !status.is_success() {
            anyhow::bail!(GatewayError::Api {
                status: status.as_u16(),
                message: body,
            });
        }
        Ok(body)
    }

    /// POST /v1/{modality}/generations
    pub async fn submit(
        &self,
        modality: Modality,
        req: &SubmitJobRequest,
    ) -> Result<SubmitJobResponse> {
        let body = self
            .send(self.http.post(&self.url(&format!("/v1/{}/generations", modality.as_str()))).json(req))
            .await?;
        serde_json::from_str(&body)
            .with_context(|| format!("failed to parse submit response: {body}"))
    }

    /// GET /v1/jobs/{job_id}
    pub async fn query_job(&self, job_id: &str) -> Result<JobResponse> {
        let body = self
            .send(self.http.get(&self.url(&format!("/v1/jobs/{job_id}"))))
            .await?;
        serde_json::from_str(&body)
            .with_context(|| format!("failed to parse job response: {body}"))
    }

    /// GET /v1/models — gateway-driven catalog; the CLI never hardcodes prices.
    pub async fn list_models(&self) -> Result<ModelsResponse> {
        let body = self.send(self.http.get(&self.url("/v1/models"))).await?;
        serde_json::from_str(&body)
            .with_context(|| format!("failed to parse models response: {body}"))
    }

    /// GET /v1/account/balance
    pub async fn balance(&self) -> Result<BalanceResponse> {
        let body = self
            .send(self.http.get(&self.url("/v1/account/balance")))
            .await?;
        serde_json::from_str(&body)
            .with_context(|| format!("failed to parse balance response: {body}"))
    }
}

use serde::{Deserialize, Serialize};

/// Modality of generation. Every modality speaks the same async job protocol.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum Modality {
    Image,
    Video,
    Music,
    Speech,
}

impl Modality {
    pub fn as_str(&self) -> &'static str {
        match self {
            Modality::Image => "image",
            Modality::Video => "video",
            Modality::Music => "music",
            Modality::Speech => "speech",
        }
    }

    pub fn plural(&self) -> &'static str {
        match self {
            Modality::Image => "images",
            Modality::Video => "videos",
            Modality::Music => "music",
            Modality::Speech => "speech",
        }
    }

    pub fn output_ext(&self) -> &'static str {
        match self {
            Modality::Image => "png",
            Modality::Video => "mp4",
            Modality::Music => "wav",
            Modality::Speech => "wav",
        }
    }
}

/// Request body for POST /v1/{modality}/generations.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SubmitJobRequest {
    pub model: String,
    pub prompt: String,
    /// Reference input (URL or data URI): image for i2i/i2v, audio for voice clone, etc.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub reference: Option<String>,
    /// Provider/gateway passthrough parameters (ratio, duration_seconds, size, ...)
    #[serde(skip_serializing_if = "Option::is_none")]
    pub params: Option<serde_json::Map<String, serde_json::Value>>,
}

/// Response of a successful submit (HTTP 202).
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SubmitJobResponse {
    pub job_id: String,
    pub state: JobState,
    pub credits_charged: f64,
    pub balance: f64,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum JobState {
    Queued,
    Running,
    Succeeded,
    Failed,
    Canceled,
}

impl JobState {
    pub fn is_terminal(&self) -> bool {
        matches!(self, JobState::Succeeded | JobState::Failed | JobState::Canceled)
    }

    pub fn is_success(&self) -> bool {
        matches!(self, JobState::Succeeded)
    }
}

impl std::fmt::Display for JobState {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(match self {
            JobState::Queued => "queued",
            JobState::Running => "running",
            JobState::Succeeded => "succeeded",
            JobState::Failed => "failed",
            JobState::Canceled => "canceled",
        })
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct JobOutput {
    #[serde(rename = "type")]
    pub kind: String,
    pub url: String,
    #[serde(default)]
    pub format: Option<String>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct JobError {
    pub code: String,
    #[serde(default)]
    pub message: Option<String>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct JobResponse {
    pub job_id: String,
    pub model: String,
    pub state: JobState,
    #[serde(default)]
    pub outputs: Vec<JobOutput>,
    #[serde(default)]
    pub credits_charged: f64,
    #[serde(default)]
    pub error: Option<JobError>,
}

