        std::fs::create_dir_all(&dir)?;
        let path = Self::config_path()?;
        std::fs::write(&path, toml::to_string_pretty(self)?)?;
        Ok(())
    }

    /// Resolve API key: env var > config file
    pub fn resolve_api_key(&self) -> Result<String> {
        if let Ok(key) = std::env::var("ANYGEN_API_KEY") {
            if !key.is_empty() {
                return Ok(key);
            }
        }
        self.api_key
            .clone()
            .filter(|k| !k.is_empty())
            .context("API key not configured. Run `anygen login` or set ANYGEN_API_KEY.")
    }

    /// Resolve base URL: ANYGEN_BASE_URL env > config
    pub fn resolve_base_url(&self) -> String {
        if let Ok(url) = std::env::var("ANYGEN_BASE_URL") {
            if !url.is_empty() {
                return url;
            }
        }
        self.base_url.clone()
    }

    pub fn get(&self, key: &str) -> Option<String> {
        match key {
            "api_key" => self.api_key.as_ref().map(|k| Self::mask_key(k)),
            "base_url" => Some(self.base_url.clone()),
            "output_dir" => Some(self.output_dir.clone()),
            "model_image" => Some(self.model_image.clone()),
            "model_video" => Some(self.model_video.clone()),
            "model_music" => Some(self.model_music.clone()),
            "model_speech" => Some(self.model_speech.clone()),
            "timeout_secs" => Some(self.timeout_secs.to_string()),
            _ => None,
        }
    }

    pub fn set(&mut self, key: &str, value: &str) -> Result<()> {
        match key {
            "api_key" => self.api_key = Some(value.into()),
            "base_url" => self.base_url = value.into(),
            "output_dir" => self.output_dir = value.into(),
            "model_image" => self.model_image = value.into(),
            "model_video" => self.model_video = value.into(),
            "model_music" => self.model_music = value.into(),
            "model_speech" => self.model_speech = value.into(),
            "timeout_secs" => self.timeout_secs = value.parse().context("must be a number")?,
            _ => anyhow::bail!("unknown config key: {key}"),
        }
        Ok(())
    }

    pub const CONFIG_KEYS: &'static [&'static str] = &[
        "api_key",
        "base_url",
        "output_dir",
        "model_image",
        "model_video",
        "model_music",
        "model_speech",
        "timeout_secs",
    ];

    fn mask_key(k: &str) -> String {
        let chars: Vec<char> = k.chars().collect();
        if chars.len() <= 12 {
            k.to_string()
        } else {
            format!("{}...{}", &chars[..8].iter().collect::<String>(), &chars[chars.len() - 4..].iter().collect::<String>())
        }
    }
}

