use anyhow::{Context, Result};
use futures_util::StreamExt;
use indicatif::{ProgressBar, ProgressStyle};
use std::path::Path;
use tokio::io::AsyncWriteExt;

pub async fn download_file(url: &str, output: &Path, quiet: bool) -> Result<()> {
    let resp = reqwest::get(url).await.context("failed to start download")?;

    if !resp.status().is_success() {
        anyhow::bail!(
            "download failed with status {}: output URL may have expired",
            resp.status()
        );
    }

    let total = resp.content_length();

    let pb = if !quiet {
        let pb = if let Some(total) = total {
            let pb = ProgressBar::new(total);
            pb.set_style(
                ProgressStyle::default_bar()
                    .template("{spinner:.green} [{bar:40.cyan/blue}] {bytes}/{total_bytes} ({eta})")
                    .unwrap()
                    .progress_chars("=> "),
            );
            pb
        } else {
            let pb = ProgressBar::new_spinner();
            pb.set_style(
                ProgressStyle::default_spinner()
                    .template("{spinner:.green} downloaded {bytes}")
                    .unwrap(),
            );
            pb
        };
        Some(pb)
    } else {
        None
    };

    if let Some(parent) = output.parent() {
        if !parent.exists() {
            std::fs::create_dir_all(parent)?;
        }
    }

    let mut file = tokio::fs::File::create(output)
        .await
        .with_context(|| format!("cannot create {}", output.display()))?;

    let mut stream = resp.bytes_stream();
    let mut downloaded: u64 = 0;

    while let Some(chunk) = stream.next().await {
        let chunk = chunk.context("error reading download stream")?;
        file.write_all(&chunk).await?;
        downloaded += chunk.len() as u64;
        if let Some(pb) = &pb {
            pb.set_position(downloaded);
        }
    }

    file.flush().await?;

    if let Some(pb) = &pb {
        pb.finish_with_message("download complete");
    }

    Ok(())
}

use anyhow::Result;
use std::time::{Duration, Instant};

use crate::client::types::{JobResponse, JobState};
use crate::client::GatewayClient;
use crate::ui;

pub struct PollOptions {
    pub timeout: Duration,
    pub initial_interval: Duration,
    #[allow(dead_code)]
    pub strict: bool,
}

impl Default for PollOptions {
    fn default() -> Self {
        Self {
            timeout: Duration::from_secs(600),
            initial_interval: Duration::from_secs(2),
            strict: false,
        }
    }
}

pub enum PollResult {
    Completed(JobResponse),
    TimedOut {
        job_id: String,
        last_state: JobState,
        elapsed: Duration,
    },
}

pub async fn poll_until_done(
    client: &GatewayClient,
    job_id: &str,
    opts: &PollOptions,
    quiet: bool,
) -> Result<PollResult> {
    let start = Instant::now();
    let mut interval = opts.initial_interval;
    let max_interval = Duration::from_secs(30);

    let spinner = if !quiet {
        Some(ui::create_poll_spinner(job_id))
    } else {
        None
    };

    loop {
        let elapsed = start.elapsed();
        if opts.timeout.as_secs() > 0 && elapsed >= opts.timeout {
            if let Some(sp) = &spinner {
                sp.finish_and_clear();
            }
            return Ok(PollResult::TimedOut {
                job_id: job_id.to_string(),
                last_state: JobState::Running,
                elapsed,
            });
        }

        if let Some(sp) = &spinner {
            sp.set_message(format!(
                "polling {job_id} ({:.0}s elapsed)...",
                elapsed.as_secs_f64()
            ));
        }

        match client.query_job(job_id).await {
            Ok(resp) => {
                if let Some(sp) = &spinner {
                    sp.set_message(format!(
                        "{job_id} — state: {} ({:.0}s)",
                        resp.state,
                        elapsed.as_secs_f64()
                    ));
                }
                if resp.state.is_terminal() {
                    if let Some(sp) = &spinner {
                        sp.finish_and_clear();
                    }
                    return Ok(PollResult::Completed(resp));
                }
            }
            Err(e) => {
                if let Some(sp) = &spinner {
                    sp.set_message(format!("poll error: {e}, retrying..."));
                }
            }
        }

        tokio::time::sleep(interval).await;
        interval = (interval * 2).min(max_interval);
    }
}

