use anyhow::Result;
use clap::{Parser, Subcommand};

// Shared library modules so `anygen` and `anygen-mockd` binaries compile them once.
use anygen_cli::{cli, client::types::Modality, client::GatewayClient, config::AppConfig, ui};

#[derive(Parser)]
#[command(
    name = "anygen",
    about = "One CLI + one credit balance for every generative AI model",
    version
)]
struct Cli {
    /// Override gateway URL (default https://api.anygen.dev; env ANYGEN_BASE_URL also works)
    #[arg(long, global = true)]
    base_url: Option<String>,

    /// Override API key (env ANYGEN_API_KEY also works)
    #[arg(long, global = true)]
    api_key: Option<String>,

    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand)]
enum Commands {
    /// Generate an image (nano-banana, seedream-4.0, ...)
    Image(cli::generate::GenerateArgs),

    /// Generate a video (seedance-2.5, ...)
    Video(cli::generate::GenerateArgs),

    /// Generate music from a prompt/lyrics
    Music(cli::generate::GenerateArgs),

    /// Text-to-speech
    Speech(cli::generate::GenerateArgs),

    /// Connect your account: store the ag-sk-... API key
    Login(cli::auth::LoginArgs),

    /// Remove the stored API key
    Logout,

    /// Show remaining credits
    Balance,

    /// List available models with credit pricing
    Models(cli::models::ModelsArgs),

    /// Query job status
    Status(cli::jobs::StatusArgs),

    /// Download outputs of a finished job
    Download(cli::jobs::DownloadArgs),

    /// Local job history
    List(cli::jobs::ListArgs),

    /// Manage configuration
    Config(cli::config::ConfigArgs),
}

#[tokio::main]
async fn main() {
    let cli = Cli::parse();

    let result = run(cli).await;

    if let Err(e) = result {
        ui::print_error(&format!("{e:#}"));
        std::process::exit(1);
    }
}

async fn run(cli: Cli) -> Result<()> {
    let mut cfg = AppConfig::load()?;

    // Auth-free commands first.
    match &cli.command {
        Commands::Logout => return cli::auth::logout().await,
        Commands::Config(args) => return cli::config::execute(args.command.clone()).await,
        Commands::List(args) => return cli::jobs::list(args).await,
        _ => {}
    }

    let base_url = cli
        .base_url
        .clone()
        .unwrap_or_else(|| cfg.resolve_base_url());
    let api_key = cli
        .api_key
        .clone()
        .or_else(|| cfg.resolve_api_key().ok());

    // Login should not require an existing key.
    if let Commands::Login(args) = &cli.command {
        if args.key.is_none() && api_key.is_none() {
            return cli::auth::login(&mut cfg, args).await;
        }
    }

    let api_key = api_key.ok_or_else(|| {
        anyhow::anyhow!("API key not configured. Run `anygen login` or set ANYGEN_API_KEY.")
    })?;
    let client = GatewayClient::new(&base_url, &api_key)?;

    match cli.command {
        Commands::Image(args) => cli::generate::generate(&client, &cfg, Modality::Image, args).await,
        Commands::Video(args) => cli::generate::generate(&client, &cfg, Modality::Video, args).await,
        Commands::Music(args) => cli::generate::generate(&client, &cfg, Modality::Music, args).await,
        Commands::Speech(args) => cli::generate::generate(&client, &cfg, Modality::Speech, args).await,
        Commands::Login(args) => cli::auth::login(&mut cfg, &args).await,
        Commands::Logout => unreachable!(),
        Commands::Balance => cli::auth::balance(&client).await,
        Commands::Models(args) => cli::models::models(&client, &args).await,
        Commands::Status(args) => cli::jobs::status(&client, &args).await,
        Commands::Download(args) => cli::jobs::download(&cfg, &client, &args).await,
        Commands::List(_) | Commands::Config(_) => unreachable!(),
    }
}

