use anyhow::{Context, Result};
use rusqlite::{params, Connection};
use serde::Serialize;

use crate::config::AppConfig;

#[derive(Debug, Serialize)]
pub struct JobRecord {
    pub job_id: String,
    pub prompt: String,
    pub model: String,
    pub modality: String,
    pub status: String,
    pub credits: f64,
    pub output_url: Option<String>,
    pub output_path: Option<String>,
    pub created_at: String,
    pub updated_at: String,
}

pub struct TaskStore {
    conn: Connection,
}

impl TaskStore {
    #[allow(dead_code)]
    pub fn open_in_memory() -> Result<Self> {
        let conn = Connection::open_in_memory()?;
        let store = Self { conn };
        store.init_tables()?;
        Ok(store)
    }

    pub fn open() -> Result<Self> {
        let path = AppConfig::config_dir()?.join("jobs.db");
        if let Some(parent) = path.parent() {
            std::fs::create_dir_all(parent)?;
        }
        let conn =
            Connection::open(&path).with_context(|| format!("failed to open database at {}", path.display()))?;
        let store = Self { conn };
        store.init_tables()?;
        Ok(store)
    }

    fn init_tables(&self) -> Result<()> {
        self.conn.execute_batch(
            "CREATE TABLE IF NOT EXISTS jobs (
                job_id      TEXT PRIMARY KEY,
                prompt      TEXT NOT NULL,
                model       TEXT NOT NULL DEFAULT '',
                modality    TEXT NOT NULL DEFAULT '',
                status      TEXT NOT NULL DEFAULT 'queued',
                credits     REAL NOT NULL DEFAULT 0,
                output_url  TEXT,
                output_path TEXT,
                created_at  TEXT NOT NULL DEFAULT (datetime('now')),
                updated_at  TEXT NOT NULL DEFAULT (datetime('now'))
            );",
        )?;
        Ok(())
    }

    pub fn insert(
        &self,
        job_id: &str,
        prompt: &str,
        model: &str,
        modality: &str,
        credits: f64,
    ) -> Result<()> {
        self.conn.execute(
            "INSERT OR REPLACE INTO jobs (job_id, prompt, model, modality, credits) \
             VALUES (?1, ?2, ?3, ?4, ?5)",
            params![job_id, prompt, model, modality, credits],
        )?;
        Ok(())
    }

    pub fn update_status(
        &self,
        job_id: &str,
        status: &str,
        output_url: Option<&str>,
    ) -> Result<()> {
        self.conn.execute(
            "UPDATE jobs SET status = ?1, output_url = COALESCE(?2, output_url), updated_at = datetime('now') WHERE job_id = ?3",
            params![status, output_url, job_id],
        )?;
        Ok(())
    }

    pub fn update_output_path(&self, job_id: &str, path: &str) -> Result<()> {
        self.conn.execute(
            "UPDATE jobs SET output_path = ?1, updated_at = datetime('now') WHERE job_id = ?2",
            params![path, job_id],
        )?;
        Ok(())
    }

    /// Fallback when the gateway-side URL expired but the file was already saved.
    pub fn get_output_path(&self, job_id: &str) -> Result<Option<String>> {
        let mut stmt = self
            .conn
            .prepare("SELECT output_path FROM jobs WHERE job_id = ?1")?;
        let mut rows = stmt.query_map(params![job_id], |row| row.get::<_, Option<String>>(0))?;
        Ok(rows.next().transpose()?.flatten())
    }

    pub fn list(&self, limit: usize, status_filter: Option<&str>) -> Result<Vec<JobRecord>> {
        let mut results = Vec::new();

        if let Some(s) = status_filter.filter(|s| *s != "all") {
            let mut stmt = self.conn.prepare(
                "SELECT job_id, prompt, model, modality, status, credits, output_url, output_path, created_at, updated_at \
                 FROM jobs WHERE status = ?1 ORDER BY created_at DESC LIMIT ?2",
            )?;
            let rows = stmt.query_map(params![s, limit], Self::map_row)?;
            for row in rows {
                results.push(row?);
            }
        } else {
            let mut stmt = self.conn.prepare(
                "SELECT job_id, prompt, model, modality, status, credits, output_url, output_path, created_at, updated_at \
                 FROM jobs ORDER BY created_at DESC LIMIT ?1",
            )?;
            let rows = stmt.query_map(params![limit], Self::map_row)?;
            for row in rows {
                results.push(row?);
            }
        }

        Ok(results)
    }

    fn map_row(row: &rusqlite::Row) -> rusqlite::Result<JobRecord> {
        Ok(JobRecord {
            job_id: row.get(0)?,
            prompt: row.get(1)?,
            model: row.get(2)?,
            modality: row.get(3)?,
            status: row.get(4)?,
            credits: row.get(5)?,
            output_url: row.get(6)?,
            output_path: row.get(7)?,
            created_at: row.get(8)?,
            updated_at: row.get(9)?,
        })
    }
}

