use console::style;
use indicatif::{ProgressBar, ProgressStyle};

use crate::client::types::JobState;

pub fn create_poll_spinner(job_id: &str) -> ProgressBar {
    let pb = ProgressBar::new_spinner();
    pb.set_style(
        ProgressStyle::default_spinner()
            .template("{spinner:.cyan} {msg}")
            .unwrap(),
    );
    pb.set_message(format!("waiting for {job_id}..."));
    pb.enable_steady_tick(std::time::Duration::from_millis(120));
    pb
}

pub fn print_job_created(job_id: &str, credits_charged: f64, balance: f64) {
    eprintln!(
        "{} Job created: {}",
        style("✓").green().bold(),
        style(job_id).cyan()
    );
    eprintln!(
        "  credits charged {}, balance {}",
        style(credits_charged).yellow(),
        style(balance).green()
    );
}

pub fn print_job_state(job_id: &str, state: &JobState) {
    let styled = match state {
        JobState::Succeeded => style(state).green().bold(),
        JobState::Failed | JobState::Canceled => style(state).red().bold(),
        JobState::Running => style(state).yellow(),
        JobState::Queued => style(state).dim(),
    };
    eprintln!("{}: {}", style(job_id).cyan(), styled);
}

pub fn print_timeout_hint(job_id: &str, elapsed_secs: u64) {
    eprintln!();
    eprintln!(
        "{} Timed out after {}s, but job {} is still running on the gateway.",
        style("⏳").yellow(),
        elapsed_secs,
        style(job_id).cyan()
    );
    eprintln!();
    eprintln!("Continue tracking:");
    eprintln!("  anygen status {job_id} --wait");
    eprintln!("  anygen download {job_id}");
}

pub fn print_downloaded(path: &str) {
    eprintln!(
        "{} Downloaded: {}",
        style("✓").green().bold(),
        style(path).cyan()
    );
}

pub fn print_error(msg: &str) {
    eprintln!("{} {}", style("✗").red().bold(), msg);
}
